import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = in.nextInt();
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int mx = a[i][0];
            for (int j = 1; j < m; j++) {
                if (a[i][j] > mx) {
                    mx = a[i][j];
                }
            }
            if (i > 0) sb.append(' ');
            sb.append(mx);
        }
        System.out.println(sb);
    }
}

