#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> a[i][j];
        }
    }
    for (int i = 0; i < n; i++) {
        int mx = a[i][0];
        for (int j = 1; j < m; j++) {
            if (a[i][j] > mx) {
                mx = a[i][j];
            }
        }
        if (i > 0) cout << ' ';
        cout << mx;
    }
    cout << endl;
    return 0;
}

